import * as ddb from "@aws-sdk/client-dynamodb";
import {marshall} from "@aws-sdk/util-dynamodb";
import {KeySchema, TableType, SchemaType, ExpressionGenerator} from "./schema";
import {prepareCommand} from "./util";
import _ from "lodash";

/**
 * DynamoDb {@link ddb.DeleteItemCommandInput} for a given {@link Table}
 */
interface DeleteCommand<Table, V> {
    /**
     * See {@link ddb.DeleteItemInput.Key}
     */
    key: SchemaType<KeySchema<Table>>,
    /**
     * Context values to be used in expressions generated by {@link condition}.
     */
    values?: V,
    /**
     * Function generating {@link ddb.DeleteItemInput.ConditionExpression}
     */
    condition?: ExpressionGenerator<Table, SchemaType<KeySchema<Table>> & V>
    /**
     * See {@link ddb.DeleteItemInput.ReturnValues}
     */
    return?: ddb.ReturnValue
    /**
     * See {@link ddb.DeleteItemInput.ReturnValuesOnConditionCheckFailure}
     */
    returnOnConditionFailure?: ddb.ReturnValuesOnConditionCheckFailure;
    /**
     * See {@link ddb.DeleteItemInput.ReturnItemCollectionMetrics}
     */
    returnItemsCollectionMetrics?: ddb.ReturnItemCollectionMetrics
    /**
     * See {@link ddb.DeleteItemInput.ReturnConsumedCapacity}
     */
    returnConsumedCapacity?: ddb.ReturnConsumedCapacity
}

/**
 * Create {@link ddb.DeleteItemCommandInput}.
 * @param tbl - target table
 * @param command - command parameters
 */
export function deleteItem<T extends TableType<T>, V>(tbl: T, command: DeleteCommand<T, V>): ddb.DeleteItemCommandInput {
    const context = {...command.key, ...command.values} as SchemaType<KeySchema<T>> & V
    const dynamoKey = marshall(command.key)
    const {
        attributeNames,
        attributeValues,
        key,
        attr,
        val
    } = prepareCommand(tbl, context, dynamoKey);
    const {condition} = command

    return {
        TableName: tbl.name,
        Key: marshall(command.key),
        ConditionExpression: condition?.({key, attr, val}),
        ReturnValues: command.return,
        ReturnValuesOnConditionCheckFailure: command.returnOnConditionFailure,
        ReturnItemCollectionMetrics: command.returnItemsCollectionMetrics,
        ReturnConsumedCapacity: command.returnConsumedCapacity,
        ExpressionAttributeNames: !_.isEmpty(attributeNames) ? attributeNames : undefined,
        ExpressionAttributeValues: !_.isEmpty(attributeValues) ? attributeValues : undefined,
    };
}

/**
 * Create {@link ddb.DeleteItemCommand}.
 * @param tbl - target table
 * @param command - command parameters
 */
export function deleteCommand<T extends TableType<T>, V>(tbl: T, command: DeleteCommand<T, V>): ddb.DeleteItemCommand {
    return new ddb.DeleteItemCommand(deleteItem(tbl, command))
}
